1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Shared formatting for an owner's customer code: {@code <CITY3>-<LAST3>-<NNNN>}, where
7	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
8	 * three of the last name and NNNN a 4-digit zero-padded per-city sequence
9	 * (e.g. {@code LON-SMI-0007}).
10	 */
11	final class OwnerCustomerCodes {
12	
13	    private OwnerCustomerCodes() {
14	    }
15	
16	    /** Format {@code city}, {@code lastName} and {@code sequence} as {@code <CITY3>-<LAST3>-<NNNN>}. */
17	    static String format(String city, String lastName, int sequence) {
18	        return prefix(city) + "-" + prefix(lastName) + "-" + String.format("%04d", sequence);
19	    }
20	
21	    /** The upper-cased first three letters of {@code value}, ignoring any non-letters. */
22	    private static String prefix(String value) {
23	        StringBuilder letters = new StringBuilder(3);
24	        for (int i = 0; value != null && i < value.length() && letters.length() < 3; i++) {
25	            char c = value.charAt(i);
26	            if (Character.isLetter(c)) {
27	                letters.append(c);
28	            }
29	        }
30	        return letters.toString().toUpperCase(Locale.ROOT);
31	    }
32	}
