208	     * @param name to test
209	     * @return true if pet name is already in use
210	     */
211	    public Pet getPet(String name, boolean ignoreNew) {
212	        name = name.toLowerCase();
213	        for (Pet pet : getPetsInternal()) {
214	            if (!ignoreNew || !pet.isNew()) {
215	                String compName = pet.getName();
216	                compName = compName.toLowerCase();
217	                if (compName.equals(name)) {
