     * falling back to the fixed city-to-region table, or 'UNKNOWN' when neither is known. */
    default String locality(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Locality.forCityAndPostcode(owner.getCity(), owner.getPostcode());
    }

